CREATE TABLE users (
  id INT PRIMARY KEY,
  org_id INT REFERENCES orgs(id)
);
CREATE OR REPLACE VIEW active AS SELECT * FROM users u JOIN orgs o ON u.org_id = o.id;
CREATE FUNCTION total() RETURNS INT AS $$ SELECT count(*) FROM users $$ LANGUAGE sql;
CREATE PERFETTO TABLE weird AS SELECT 1;
CREATE VIEW IF NOT EXISTS recovered AS WITH x AS (SELECT * FROM f(VALUES (1))) SELECT * FROM x;
ALTER TABLE users ADD CONSTRAINT fk FOREIGN KEY (org_id) REFERENCES orgs(id);
